TLM.f("Tempora/PentEpi6-0",{"officium":"Dominica VI quæ superfuit Post Epiphaniam","rule":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, semper rationabília meditántes, quæ tibi sunt plácita, et dictis exsequámur et factis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Thessalonicénses"},{"k":"ref","la":"1 Thess 1:2-10"},{"k":"text","la":"Fratres: Grátias ágimus Deo semper pro ómnibus vobis, memóriam vestri faciéntes in oratiónibus nostris sine intermissióne, mémores óperis fídei vestræ, et labóris, et caritátis, et sustinéntiæ spei Dómini nostri Jesu Christi, ante Deum et Patrem nostrum: sciéntes, fratres, dilécti a Deo. electiónem vestram: quia Evangélium nostrum non fuit ad vos in sermóne tantum, sed et in virtúte, et in Spíritu Sancto, et in plenitúdine multa, sicut scitis quales fuérimus in vobis propter vos. Et vos imitatóres nostri facti estis, et Dómini, excipiéntes verbum in tribulatióne multa, cum gáudio Spíritus Sancti: ita ut facti sitis forma ómnibus credéntibus in Macedónia et in Achája. A vobis enim diffamátus est sermo Dómini, non solum in Macedónia et in Achája, sed et in omni loco fides vestra, quæ est ad Deum, profécta est, ita ut non sit nobis necésse quidquam loqui. Ipsi enim de nobis annúntiant, qualem intróitum habuérimus ad vos: et quómodo convérsi estis ad Deum a simulácris, servíre Deo vivo et vero, et exspectáre Fílium ejus de cœlis quem suscitávit ex mórtuis Jesum, qui erípuit nos ab ira ventúra."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 13:31-35"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis parábolam hanc: Símile est regnum cœlórum grano sinápis, quod accípiens homo seminávit in agro suo: quod mínimum quidem est ómnibus semínibus: cum autem créverit, majus est ómnibus oléribus, et fit arbor, ita ut vólucres cœli véniant et hábitent in ramis ejus. Aliam parábolam locútus est eis: Símile est regnum cœlórum ferménto, quod accéptum múlier abscóndit in farínæ satis tribus, donec fermentátum est totum. Hæc ómnia locútus est Jesus in parábolis ad turbas: et sine parábolis non loquebátur eis: ut implerétur quod dictum erat per Prophétam dicéntem: Apériam in parábolis os meum, eructábo abscóndita a constitutióne mundi."}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Hæc nos oblátio, Deus, mundet, quǽsumus, et rénovet, gubérnet et prótegat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Cœléstibus, Dómine, pasti delíciis: quǽsumus; ut semper éadem, per quæ veráciter vívimus, appétimus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva."},"b81ec32c36a765af":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da uvijek pravo mislimo i da ono što je tebi ugodno izvršimo riječima i djelima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c10b84a4ae5c41e1":{"t":"1 Sol 1, 2-10\nČitanje Poslanice bl. Pavla apostola Solunjanima. Braćo: uvijek zahvaljujemo Bogu za sve vas, spominjući vas u svojim molitvama, sjećajući se bez prestanka vaše djelotvorne vjere, i truda i ljubavi i postojane nade u našega Gospodina Isusa Krista pred Bogom, našim Ocem, jer znamo, od Boga ljubljena braćo, da ste izabrani. Naše evanđelje nije došlo k vama samo po propovijedanju, nego po snazi odozgo, po djelovanju Duha Svetoga i po potpunom uvjerenju. Znate dobro kakvi smo bili među vama radi Vas. – Vi ste tako nasljedovali nas i Gospodina, pošto ste primili nauku u velikoj nevolji, s radošću Duha Svetoga, da ste postali uzorom svim vjernicima u Makedoniji i Ahaji, nego se posvuda razglasila vaša vjera u Boga u tolikoj mjeri da ne treba da mi što govorimo. Drugi sami pričaju kakav smo doček imali kod vas i kako ste se od idola obratili k Bogu, da služite živome i pravome Bogu, i da s neba očekujete njegova Sina Isusa, kojega je uskrisio od mrtvih, i koji nas je izbavio od budućega gnjeva."},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>."},"32f574f1daa6000b":{"t":"Mt 13, 31-35\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Reče Isus narodu ovu usporedbu: Nebesko je kraljevstvo kao zrno gorušice koje čovjek uzme i posije na svojoj njivi. Ono je doduše najmanje od svega sjemena, ali, kad uzraste, veće je od svega povrća te postane stablom tako da dolaze ptice nebeske i stanuju na njegovim granama. – I drugu usporedbu reče: Nebesko je kraljevstvo kao kvasac što ga žena uzme i pomiješa s tri mjere brašna, dok sve ne uskisne. Sve je ovo Isus govorio narodu u usporedbama, i bez usporedaba nije mu govorio, da se ispuni proročanstvo: Otvorit ću svoja usta u usporedbama i objavit ću što je bilo sakriveno od postanka svijeta."},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine."},"430c21300153da2d":{"t":"Ovaj prinos, molimo, Gospodine, neka nas očisti, obnovi, vodi i štiti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam."},"01204a4deb331f8e":{"t":"<i>Pomolimo se</i>.\nNebeskom gozbom nasićeni, molimo, Gospodine, da uvijek želimo ono što nam daje pravi život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
